import type { TokenModel } from '@lumen/design-sources';
import type { OutputFile, Target } from '../core/target.js';
import { cssLayers, type Declarations } from './cssLayers.js';
import { breakpointMinWidths, orderedBreakpoints } from './modes.js';

const HEADER = `/*
 * Do not edit directly, this file was auto-generated by design-build.
 */`;

const rule = (
  selector: string,
  declarations: Declarations,
  indent = '',
): string =>
  [
    `${indent}${selector} {`,
    ...Object.entries(declarations).map(
      ([name, value]) => `${indent}  ${name}: ${value};`,
    ),
    `${indent}}`,
  ].join('\n');

/**
 * The plain CSS themes: Lumen's custom properties with no Tailwind directive,
 * so any web app can import them. One self-contained file per brand (light on
 * `:root`, dark under `.dark`), and `all-brands.css`, where a `.<brand>` class
 * on a parent picks the brand.
 */
export const cssThemesTarget = (outDir: string): Target<TokenModel> => ({
  name: 'css-themes',
  outDir,
  emit: (model) => {
    const breakpoints = orderedBreakpoints(model);
    const minWidths = breakpointMinWidths(model);
    const layers = cssLayers(model, breakpoints);
    const [base, ...wider] = layers.breakpoints;

    const shared = [
      rule(':root', { ...layers.primitives, ...base.declarations }),
      ...wider.map(({ breakpoint, declarations }) =>
        [
          `@media (min-width: ${minWidths.get(breakpoint)}px) {`,
          rule(':root', declarations, '  '),
          '}',
        ].join('\n'),
      ),
    ];
    const themeOf = (brand: string, theme: string): Declarations => {
      const layer = layers.themes.find(
        (candidate) => candidate.brand === brand && candidate.theme === theme,
      );
      if (!layer) throw new Error(`No ${theme} theme for ${brand}`);
      return layer.declarations;
    };
    const file = (
      path: string,
      comment: string,
      rules: string[],
    ): OutputFile => ({
      path,
      contents: `${[HEADER, `/* ${comment} */`, ...shared, ...rules].join('\n\n')}\n`,
    });

    const brands = model.modesOf('brand');
    return [
      ...brands.map((brand) =>
        file(
          `${brand}.css`,
          `The ${brand} brand: light on :root, dark under .dark.`,
          [
            rule(':root', themeOf(brand, 'light')),
            rule('.dark', themeOf(brand, 'dark')),
          ],
        ),
      ),
      file(
        'all-brands.css',
        'Every brand, picked by a .<brand> class on a parent; dark under .dark.',
        brands.flatMap((brand) => [
          rule(`.${brand}`, themeOf(brand, 'light')),
          rule(`.${brand}.dark`, themeOf(brand, 'dark')),
        ]),
      ),
    ];
  },
});
